#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricConductivity::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricConductivity::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricConductivityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricConductivity::from_base(0.0).auto_unit().unit,
        ElectricConductivityUnit::SiemensPerMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "S/m".parse::<ElectricConductivityUnit>(),
        Ok(ElectricConductivityUnit::SiemensPerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "S/m").parse::<ElectricConductivity>(),
        Ok(ElectricConductivity::new(
            2.5,
            ElectricConductivityUnit::SiemensPerMeter
        ))
    );
    assert_eq!(
        "S/in".parse::<ElectricConductivityUnit>(),
        Ok(ElectricConductivityUnit::SiemensPerInch)
    );
    assert_eq!(
        format!("2.5 {}", "S/in").parse::<ElectricConductivity>(),
        Ok(ElectricConductivity::new(
            2.5,
            ElectricConductivityUnit::SiemensPerInch
        ))
    );
    assert_eq!(
        "S/ft".parse::<ElectricConductivityUnit>(),
        Ok(ElectricConductivityUnit::SiemensPerFoot)
    );
    assert_eq!(
        format!("2.5 {}", "S/ft").parse::<ElectricConductivity>(),
        Ok(ElectricConductivity::new(
            2.5,
            ElectricConductivityUnit::SiemensPerFoot
        ))
    );
    assert_eq!(
        "S/cm".parse::<ElectricConductivityUnit>(),
        Ok(ElectricConductivityUnit::SiemensPerCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "S/cm").parse::<ElectricConductivity>(),
        Ok(ElectricConductivity::new(
            2.5,
            ElectricConductivityUnit::SiemensPerCentimeter
        ))
    );
    assert_eq!(
        "µS/cm".parse::<ElectricConductivityUnit>(),
        Ok(ElectricConductivityUnit::MicrosiemensPerCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "µS/cm").parse::<ElectricConductivity>(),
        Ok(ElectricConductivity::new(
            2.5,
            ElectricConductivityUnit::MicrosiemensPerCentimeter
        ))
    );
    assert_eq!(
        "mS/cm".parse::<ElectricConductivityUnit>(),
        Ok(ElectricConductivityUnit::MillisiemensPerCentimeter)
    );
    assert_eq!(
        format!("2.5 {}", "mS/cm").parse::<ElectricConductivity>(),
        Ok(ElectricConductivity::new(
            2.5,
            ElectricConductivityUnit::MillisiemensPerCentimeter
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricConductivity>(),
        Err(ParseError::UnknownUnit)
    );
}

